using Godot;
using Arconist.Core;
using Arconist.Bridge;
using System.Text.Json;
namespace Arconist.GodotApp;
public static class WideningValidation
{
 sealed class Clock:IMonotonicClock{public long Milliseconds{get;set;}}
 public static async void Run(Node owner,SpatialTrack track,string evidenceDir)
 {
 int passed=0,failed=0;var outcomes=new List<object>();var projections=new List<object>();var observations=new List<object>();
 void C(bool ok,string why){if(!ok)throw new Exception(why);}
 void T(string name,Action test){try{test();passed++;outcomes.Add(new{name,status="PASS"});GD.Print("PASS W2-02 "+name);}catch(Exception e){failed++;outcomes.Add(new{name,status="FAIL",error=e.ToString()});GD.Print("FAIL W2-02 "+name+": "+e.Message);}}
 string Load(string file)=>Godot.FileAccess.GetFileAsString("res://content/"+file+".aff");
 (GameplaySession,Clock,SpatialContactAdapter) New(string name){var clock=new Clock();var s=new GameplaySession(clock);s.Start(Load(name),profile:ChartProfile.S01Mixed);clock.Milliseconds=3002;s.Frame();track.Refresh(s.Core);return(s,clock,new SpatialContactAdapter(s,track));}
 void F(GameplaySession s,Clock c,int e){c.Milliseconds=e+3002;s.Frame();track.Refresh(s.Core);}
 void Prep(GameplaySession s,Clock c){foreach(int e in new[]{500,501,502,750,1000,1500})F(s,c,e);}
 Vector2 Screen(float x)=>track.Camera.UnprojectPosition(SpatialTrack.World(x,0,0));
 T("all five production chart resources parse through normal loader",()=>{foreach(string n in new[]{"native_widen_control","native_widen_camera","native_widen_lanes","widen_lanes_practice","widen_camera_practice"})C(Chart.Parse(Load(n),ChartProfile.S01Mixed).JudgmentUnits>0,n);});
 foreach(string name in new[]{"control","camera","lanes"})T("E039 actual camera ray adapter core judgment "+name,()=>{var(s,c,p)=New("native_widen_"+name);Prep(s,c);foreach(int x in new[]{40,950}){var screen=Screen(x);C(track.GetViewport().GetVisibleRect().HasPoint(screen),"visible input coordinate");var pair=track.PickLanes(screen,out var point);C(Math.Abs(point.X-x)<.15f,"ray inverse");int expected=x==40?4:name=="lanes"?6:5;C(pair.Primary==expected&&pair.Secondary==(name=="camera"&&x==40?3:0),"native pair");C(p.Press(100,screen),"production DOWN");C(s.Core!.Contacts.Single().Lanes.Primary==pair.Primary&&s.Core.Contacts.Single().SecondaryLane==pair.Secondary,"core computed from actual world point");observations.Add(new{name,x,pair,point,s.Core.Pure,s.Core.Score,health=s.Core.Health,candidates=s.Core.Candidates.ToArray(),classifications=s.Core.Classifications.ToArray()});C(p.Release(100)&&s.Core.ContactCount==0&&s.HeldCount==0,"UP cleanup");}int pure=name=="control"?0:1;C(s.Core!.Pure==pure&&s.Core.Score==(pure==0?0:5000001)&&s.Core.Health==(pure==0?0:40.20000076293945f),"native recorder");F(s,c,1501);C(s.Core.Pure==pure&&s.Core.RecorderTrace.Count==0,"no frame duplicate");s.Home();track.Refresh(null);});
 T("ENGINEERING accepted-region meshes reflect scalar without FOV claim",()=>{var(s,c,p)=New("native_widen_camera");var pos=track.Camera.Position;float fov=track.Camera.Fov;Prep(s,c);C(track.WideningVisible&&track.WideningRegions.Any(r=>r.Lane==3&&r.Secondary&&r.MinX<40&&r.MaxX>40),"secondary F overlay");C(track.Camera.Position==pos&&track.Camera.Fov==fov,"no fabricated FOV change");C(track.GetNode<Node3D>("EngineeringInputRegions").GetChildren().OfType<MeshInstance3D>().Any(m=>m.Visible&&m.Mesh is BoxMesh),"actual geometry");s.Home();track.Refresh(null);C(!track.WideningVisible&&track.WideningRegions.Count==0,"menu cleanup");});
 T("outer geometry and note target become eligible through W",()=>{var(s,c,p)=New("native_widen_lanes");F(s,c,500);C(!track.WideningRegions.Any(r=>r.Lane==6),"outer not yet open");F(s,c,501);F(s,c,502);C(track.WideningRegions.Any(r=>r.Lane==6&&r.MinX<950&&r.MaxX>950),"positive W selects whole original outer domain");F(s,c,1500);var n=s.Core!.Notes.Single(n=>n.Lane==6);C(track.TapVisual(n.Id)!.Visible&&track.PickLanes(Screen(SpatialTrack.NativeX(6)),out _).Primary==6,"actual target alignment");s.Home();});
 T("F6 and actual resized viewport preserve both native probe selections",()=>{var viewport=(SubViewport)track.GetViewport();var container=(SubViewportContainer)viewport.GetParent();bool stretch=container.Stretch;var old=viewport.Size;container.Stretch=false;try{foreach(var size in new[]{new Vector2I(610,550),new Vector2I(732,660)})foreach(bool alt in new[]{false,true})foreach(string n in new[]{"camera","lanes"}){viewport.Size=size;C(viewport.Size==size,"actual viewport size");var(s,c,p)=New("native_widen_"+n);track.SetView(alt);Prep(s,c);foreach(int x in new[]{40,950}){var screen=Screen(x);var pair=track.PickLanes(screen,out var point);C(viewport.GetVisibleRect().HasPoint(screen)&&pair.Primary==(x==40?4:n=="lanes"?6:5)&&pair.Secondary==(n=="camera"&&x==40?3:0),"roundtrip");projections.Add(new{n,x,alt,width=size.X,height=size.Y,pair,point,screen});}s.Home();}}finally{viewport.Size=old;container.Stretch=stretch;track.SetView(false);}});
 T("invalid outside and parallel rays fail without judgments",()=>{var(s,c,p)=New("native_widen_camera");Prep(s,c);C(!p.Press(100,new Vector2(float.NaN,0))&&!p.Press(100,new Vector2(-5,-5)),"invalid viewport input");C(!SpatialTrack.GroundIntersection(Vector3.Zero,Vector3.Right,out _),"parallel");C(s.Core!.Pure==0&&s.Core.ContactCount==0,"no manufactured input");s.Home();});
 T("duplicate fresh pointer and MOVE cannot double record",()=>{var(s,c,p)=New("native_widen_camera");Prep(s,c);C(p.Press(100,Screen(40)),"first");int id=s.Core!.Contacts.Single().Id;p.Release(100);C(p.Press(101,Screen(40))&&s.Core.Contacts.Single().Id!=id&&s.Core.Pure==1&&s.Core.Classifications.Single().Outcome=="guard_consumed","child-independent ground consumed guard");p.Move(101,Screen(950));C(s.Core.Pure==1,"MOVE");p.Release(101,true);C(s.Core.ContactCount==0,"cancel");s.Home();});
 T("60second modal freeze and paused release survive renderer refresh",()=>{var(s,c,p)=New("native_widen_camera");foreach(int e in new[]{500,501,750})F(s,c,e);p.Press(100,Screen(40));C(s.Pause(),"pause");float g=s.Core!.Widening.G;c.Milliseconds+=60000;s.Frame();for(int i=0;i<10;i++)track.Refresh(s.Core);C(s.Core.Timeline.EffectiveTime==750&&s.Core.Widening.G==g&&!p.Press(101,Screen(40)),"no paused progression/input");C(p.Release(100)&&s.Core.ContactCount==0,"paused UP");C(s.Resume()&&!s.PauseModalActive,"dismiss");c.Milliseconds+=750;s.Frame();track.Refresh(s.Core);C(p.Press(100,Screen(40))&&s.Core.Pure==1,"fresh DOWN at1500 restored");p.Release(100);s.Home();});
 foreach(string type in new[]{"lanes","camera"})T("full "+type+" practice through production spatial adapter results replay",()=>{var(s,c,p)=New("widen_"+type+"_practice");int end=s.Core!.Chart.EndTime;for(int e=1;e<=end+1;e++){F(s,c,e);foreach(var n in s.Core.Notes.Where(n=>n.Start==e)){float x=type=="camera"?40:SpatialTrack.NativeX(n.Lane);C(p.Press(100,Screen(x)),"chart tapDOWN");p.Release(100);}var hold=s.Core.Holds.Single();if(e==hold.Start)C(p.Press(100,Screen(type=="camera"?40:SpatialTrack.NativeX(3))),"holdDOWN");if(e==hold.End)p.Release(100);}int expected=type=="lanes"?13:11;C(s.Core.Result?.Score==10000000+expected&&s.Core.Pure==expected&&s.Core.Lost==0&&s.Core.ContactCount==0&&s.HeldCount==0,"complete native-backed components / reconstructed result");p.Prune();C(p.Count==0,"adapter cleanup");s.Start(Load("widen_"+type+"_practice"),profile:ChartProfile.S01Mixed);track.Refresh(s.Core);C(s.Core!.Widening.W==0&&s.Core.Widening.G==1&&s.Core.Pure==0&&s.Core.Holds.All(h=>!h.Latched)&&s.Core.Widening.Controls.All(x=>!x.Processed),"fresh replay");s.Home();track.Refresh(null);});
 var bgm=new GodotBgmBackend();owner.AddChild(bgm);var clock=new Clock();var audible=new GameplaySession(clock,bgm);var diagnostics=new List<BgmDiagnostic>();audible.Audio!.Diagnostic+=diagnostics.Add;
 T("actual Godot widened chart bundled audio strict startup",()=>{audible.Start(Load("widen_lanes_practice"),0,"W2-02-widen-lanes","res://content/audio/clockwork_steps.wav.bytes",profile:ChartProfile.S01Mixed);clock.Milliseconds=3000;audible.Frame();C(!bgm.Player.Playing,"strict equality");clock.Milliseconds=3002;audible.Frame();C(bgm.Player.Playing&&audible.Audio!.Starts==1,"backend response only");});
 await owner.ToSignal(owner.GetTree().CreateTimer(.05),SceneTreeTimer.SignalName.Timeout);
 T("widened audio pause seek unpause and menu unload",()=>{foreach(int e in new[]{2000,2001,2500}){clock.Milliseconds=e+3002;audible.Frame();}audible.Pause();clock.Milliseconds+=60000;audible.Frame();C(audible.Core!.Widening.W==.5f&&audible.Core.Timeline.EffectiveTime==2500&&bgm.Player.StreamPaused,"frozen transition/audio");C(audible.Resume()&&diagnostics.Any(d=>d.Kind=="BGM_SEEK_REQUEST"&&d.SeekMilliseconds==2500),"logical seek");audible.Home();C(bgm.Player.Stream==null&&!bgm.Player.Playing,"unload");});
 bgm.StopAndUnload();owner.RemoveChild(bgm);bgm.QueueFree();track.Refresh(null);track.SetView(false);
 await owner.ToSignal(owner.GetTree().CreateTimer(.1),SceneTreeTimer.SignalName.Timeout);
 File.WriteAllText(Path.Combine(evidenceDir,"widening-headless.json"),JsonSerializer.Serialize(new{passed,failed,skipped=0,outcomes,projections,observations,diagnostics,human="PENDING",newIndependent="NOT RUN"},new JsonSerializerOptions{WriteIndented=true}));GD.Print($"W2-02 headless: {passed+failed}; passed:{passed}; failed:{failed}; skipped:0");owner.GetTree().Quit(failed==0?0:1);
 }
}
